window.RP_SESSION={"id":"S-019568f4cfb4","messages":[{"id":"RP-0246584","time":"2026-08-22T10:58:00+09:00","room":"RP","name":"위크 골든리프","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"타악기 연주에 맛들린 위크. 버려진 냄비나 쇳조각, 나뭇조각, 돌... 그리고 풀무 페달에서 가져온 묵직한 베이스까지. 어설프게 드럼 세트가 완성됩니다.","characters":["P-d129df648db5"]},{"id":"RP-0246585","time":"2026-08-22T11:01:00+09:00","room":"RP","name":"위크 골든리프","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"\"간단한 것부터 시작해볼까.\"","characters":["P-d129df648db5"]},{"id":"RP-0246586","time":"2026-08-22T11:01:00+09:00","room":"RP","name":"위크 골든리프","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"https://www.musicca.com/ko/drum-machine?data=90-n-44-a--5acegikmo6em7aip-","characters":["P-d129df648db5"]},{"id":"RP-0246587","time":"2026-08-22T12:45:00+09:00","room":"RP","name":"폰타니움","profile":"폰타니움","identity":"reviewed","type":"dialogue","body":"\"아이고 두야, 어디서 봉창 두들기는 소리가 나는거야?\"\n\n숙취에 절어있는 폰타니움이 눈을 찌푸린 채 비척거리며 다가옵니다.","characters":["P-9d3d027f2be0"]},{"id":"RP-0246588","time":"2026-08-22T12:45:00+09:00","room":"RP","name":"위크 골든리프","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"\"...\"\n\n아랑곳하지 않고 드럼을 두들깁니다. 뭐라 하면 한 대 칠 기세군요.","characters":["P-d129df648db5"]},{"id":"RP-0246589","time":"2026-08-22T12:47:00+09:00","room":"RP","name":"폰타니움","profile":"폰타니움","identity":"reviewed","type":"dialogue","body":"\"이봐 이봐, 오늘은 주말이라고. 즉슨 모닝콜은 스무스하게 스킵해도 되는날이라 이 말이지.\"","characters":["P-9d3d027f2be0"]},{"id":"RP-0246590","time":"2026-08-22T12:48:00+09:00","room":"RP","name":"위크 골든리프","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"\"모닝콜은 무슨, 해가 중천이다 이 주정뱅이야.\"","characters":["P-d129df648db5"]},{"id":"RP-0246591","time":"2026-08-22T12:49:00+09:00","room":"RP","name":"폰타니움","profile":"폰타니움","identity":"reviewed","type":"dialogue","body":"\"아직도 잘 모르나보군. 이 몸이 일어나면 아침. 잠들면 밤이라 이 말이지.\"","characters":["P-9d3d027f2be0"]},{"id":"RP-0246592","time":"2026-08-22T12:51:00+09:00","room":"RP","name":"폰타니움","profile":"폰타니움","identity":"reviewed","type":"dialogue","body":"\"뭐, 같이 밥이나 한끼하고 두들기는 건 어때? 나도 음악은 꽤 좋아해서.\"\n\n폰타니움이 품에서 럼을 꺼내며 말합니다.","characters":["P-9d3d027f2be0"]},{"id":"RP-0246593","time":"2026-08-22T12:53:00+09:00","room":"RP","name":"거베라 데이시","profile":"올리브","identity":"reviewed","type":"dialogue","body":"누우우가 술을 꺼냈지?","characters":["P-2a0e01fe8908"]},{"id":"RP-0246594","time":"2026-08-22T12:54:00+09:00","room":"RP","name":"거베라 데이시","profile":"올리브","identity":"reviewed","type":"dialogue","body":"귀신같이 술냄새 맡는 중인 이미 취한 엘프","characters":["P-2a0e01fe8908"]},{"id":"RP-0246595","time":"2026-08-22T12:55:00+09:00","room":"RP","name":"위크 골든리프","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"\"지금 몸이 좀 안좋아서.\"\n\n몸통에 칭칭 감긴 붕대를 보여준다.\n\n\"숨만 쉬어도 아파죽겠어.\"","characters":["P-d129df648db5"]},{"id":"RP-0246596","time":"2026-08-22T12:57:00+09:00","room":"RP","name":"폰타니움","profile":"폰타니움","identity":"reviewed","type":"dialogue","body":"\"그럴때일 수록 몸을 소독해야하는데 말이지 하하하!\"\n\n폰타니움이 술병을 흔들어 보이며 웃습니다.","characters":["P-9d3d027f2be0"]},{"id":"RP-0246597","time":"2026-08-22T12:57:00+09:00","room":"RP","name":"폰타니움","profile":"폰타니움","identity":"reviewed","type":"dialogue","body":"\"오우, 뭘 좀 아는 친구가 온 것 같구만. 동족의 냄새가 나.\"","characters":["P-9d3d027f2be0"]},{"id":"RP-0246598","time":"2026-08-22T12:58:00+09:00","room":"RP","name":"위크 골든리프","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"\"에휴, 좀만 마시지 뭐.\"","characters":["P-d129df648db5"]},{"id":"RP-0246599","time":"2026-08-22T12:58:00+09:00","room":"RP","name":"거베라 데이시","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"헤헤, 안녕하세요. 선배님. 길드에 가입 신청한 거베라입니다.\"\n\n 스을쩍 모습을 드러냅니다.","characters":["P-2a0e01fe8908"]},{"id":"RP-0246600","time":"2026-08-22T12:59:00+09:00","room":"RP","name":"폰타니움","profile":"폰타니움","identity":"reviewed","type":"dialogue","body":"\"술에는 음식이 빠질 수 없지. 조금만 기다려달라고.\"","characters":["P-9d3d027f2be0"]},{"id":"RP-0246601","time":"2026-08-22T13:02:00+09:00","room":"RP","name":"위크 골든리프","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"\"그래 뭐...\"","characters":["P-d129df648db5"]},{"id":"RP-0246602","time":"2026-08-22T13:02:00+09:00","room":"RP","name":"폰타니움","profile":"폰타니움","identity":"reviewed","type":"dialogue","body":"폰타니움이 밀가루를 반죽해 파이 틀 위에 성형한 뒤, 돼지의 간과 내장, 각종 허브와 향신채, 소금으로 간을 한 뒤 다져 틀 위에 올리고 반죽을 얹은 뒤 포크로 구멍을 뚫어 오븐에 넣습니다. 이윽고, 잘 익은 고기파이가 완성됩니다.","characters":["P-9d3d027f2be0"]},{"id":"RP-0246603","time":"2026-08-22T13:03:00+09:00","room":"RP","name":"폰타니움","profile":"폰타니움","identity":"reviewed","type":"dialogue","body":"\"자, 피를 질질 흘렸을땐 내장요리가 직빵이지. 먹고 기운내서 두들겨보라고.\"","characters":["P-9d3d027f2be0"]},{"id":"RP-0246604","time":"2026-08-22T13:04:00+09:00","room":"RP","name":"위크 골든리프","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"\"오, 맛있겠는데.\"","characters":["P-d129df648db5"]},{"id":"RP-0246605","time":"2026-08-22T13:06:00+09:00","room":"RP","name":"폰타니움","profile":"폰타니움","identity":"reviewed","type":"dialogue","body":"\"즐겨보자고.하하하!\"\n\n폰타니움이 포크로 고기파이를 한움큼 뜬 뒤 럼을 벌컥벌컥 들이키기 시작합니다.","characters":["P-9d3d027f2be0"]},{"id":"RP-0246606","time":"2026-08-22T13:12:00+09:00","room":"RP","name":"위크 골든리프","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"평소보단 조용히, 만찬을 즐깁니다.","characters":["P-d129df648db5"]},{"id":"RP-0246607","time":"2026-08-22T13:15:00+09:00","room":"RP","name":"폰타니움","profile":"폰타니움","identity":"reviewed","type":"dialogue","body":"\"그래서, 왜 만신창이가 된 채 이것저것 두들기고 있었던 거야? 무언가 두들기지 않고는 참을 수 없이 화가났다던지 그런건가?\"","characters":["P-9d3d027f2be0"]},{"id":"RP-0246608","time":"2026-08-22T13:22:00+09:00","room":"RP","name":"위크 골든리프","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"\"뭐... 비슷하지.\"","characters":["P-d129df648db5"]},{"id":"RP-0246609","time":"2026-08-22T13:37:00+09:00","room":"RP","name":"폰타니움","profile":"폰타니움","identity":"reviewed","type":"dialogue","body":"\"가끔 그럴때가 있지. 혈기왕성 하구만. 쓸데없는 일에 열이 뻗친다는 건 아직 청춘이라는 방증이거든.\"","characters":["P-9d3d027f2be0"]},{"id":"RP-0246610","time":"2026-08-22T13:47:00+09:00","room":"RP","name":"위크 골든리프","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"\"그래? 젊으니 좋네.\"","characters":["P-d129df648db5"]},{"id":"RP-0246611","time":"2026-08-22T13:53:00+09:00","room":"RP","name":"폰타니움","profile":"폰타니움","identity":"reviewed","type":"dialogue","body":"\"저기 엘프는 술 마시기도전에 뻗어버린건가?\"\n\n폰타니움이 거베라를 바라보며 말합니다.","characters":["P-9d3d027f2be0"]},{"id":"RP-0246612","time":"2026-08-22T13:53:00+09:00","room":"RP","name":"위크 골든리프","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"\"이미 좀 취한 것 같던데.\"","characters":["P-d129df648db5"]},{"id":"RP-0246613","time":"2026-08-22T13:58:00+09:00","room":"RP","name":"폰타니움","profile":"폰타니움","identity":"reviewed","type":"dialogue","body":"\"쯧쯧 대낮에 취하기나 하고 말이야. 저건 청춘이 아니라 애송이로구만.\"","characters":["P-9d3d027f2be0"]},{"id":"RP-0246614","time":"2026-08-22T14:32:00+09:00","room":"RP","name":"거베라 데이시","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"안 실례지만 몇 살이신데요?\"\n\n 난 청춘이 아니에요~","characters":["P-2a0e01fe8908"]},{"id":"RP-0246615","time":"2026-08-22T15:17:00+09:00","room":"RP","name":"폰타니움","profile":"폰타니움","identity":"reviewed","type":"dialogue","body":"\"음? 청춘이 아니라 애송이라니까 엘프 아가씨?\"","characters":["P-9d3d027f2be0"]},{"id":"RP-0246618","time":"2026-08-22T19:23:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... see you again, cowboy.","characters":[]},{"id":"RP-0246619","time":"2026-08-22T22:31:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"unresolved","type":"dialogue","body":"사진","characters":[]}]};
